var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{contentText:""},methods:{getData(){const a=window.location.origin+"/dashboard/welcomes/data";axios.get(a).then(a=>{this.contentText=a.data}).catch(a=>{console.log(a)})},updatePasive(){const a=window.location.origin+"/dashboard/welcomes";axios.post(a,{data:this.contentText}).catch(a=>{console.log(a)})}},created(){this.getData()}});